const geminiResponse = $input.first().json;
const previousData = $('Prepare Data').first().json;

let resumeData = {};

try {
  const responseText = geminiResponse?.output || geminiResponse?.text || "";

  if (!responseText) {
    throw new Error("Empty AI response");
  }

  let cleaned = responseText
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  const firstBrace = cleaned.indexOf("{");
  const lastBrace = cleaned.lastIndexOf("}");

  if (firstBrace === -1 || lastBrace === -1) {
    throw new Error("No JSON found");
  }

  cleaned = cleaned.substring(firstBrace, lastBrace + 1);
  const parsed = JSON.parse(cleaned);

  // Validation
  if (!parsed.name || !parsed.summary) {
    throw new Error("Invalid resume structure");
  }

  if (parsed.project_name || parsed.structure) {
    throw new Error("Received project JSON instead of resume JSON");
  }

  resumeData = parsed;
} catch (error) {
  console.log("Parse failed:", error.message);
  resumeData = {
    name: previousData.user_name || "",
    title: "",
    email: "",
    phone: "",
    location: "",
    summary: previousData.resume_text || "",
    skills: [],
    experience: [],
    education: [],
    projects: [],
    links: {}
  };
}

// Force structure safety
resumeData.skills = Array.isArray(resumeData.skills) ? resumeData.skills : [];
resumeData.experience = Array.isArray(resumeData.experience) ? resumeData.experience : [];
resumeData.education = Array.isArray(resumeData.education) ? resumeData.education : [];
resumeData.projects = Array.isArray(resumeData.projects) ? resumeData.projects : [];
resumeData.links = typeof resumeData.links === "object" && resumeData.links !== null ? resumeData.links : {};

return {
  json: {
    ...previousData,
    resumeData
  }
};

